from __future__ import annotations

from app import catalog, shipping


class PickJob:
    def __init__(self, order_id: int, sku: str, qty: int) -> None:
        self.order_id = order_id
        self.sku = sku
        self.qty = qty
        self.packed = False

    def mark_packed(self) -> None:
        self.packed = True

    def as_dict(self) -> dict:
        return {
            "order_id": self.order_id,
            "sku": self.sku,
            "qty": self.qty,
            "packed": self.packed,
        }


_JOBS: list[PickJob] = []


def plan_picks(order_id: int, items: list[dict]) -> list[dict]:
    jobs: list[dict] = []
    for item in items:
        sku = str(item.get("sku") or "widget")
        if not catalog.is_shippable(sku):
            continue
        job = PickJob(order_id, sku, int(item.get("qty", 1) or 1))
        _JOBS.append(job)
        jobs.append(job.as_dict())
    return jobs


def pack_next() -> dict | None:
    for job in _JOBS:
        if not job.packed:
            job.mark_packed()
            return job.as_dict()
    return None


def pending_count() -> int:
    return sum(1 for job in _JOBS if not job.packed)


def postage_for(items: list[dict]) -> float:
    return shipping.quote_shipment(items)


def jobs_for(order_id: int) -> list[dict]:
    return [job.as_dict() for job in _JOBS if job.order_id == order_id]


def reset_store() -> None:
    _JOBS.clear()

"""Internal journal for captured and voided payments."""

from __future__ import annotations


class JournalLine:
    def __init__(self, kind: str, user_id: int, amount: float, ref: str) -> None:
        self.kind = kind
        self.user_id = user_id
        self.amount = amount
        self.ref = ref

    def as_dict(self) -> dict:
        return {
            "kind": self.kind,
            "user_id": self.user_id,
            "amount": self.amount,
            "ref": self.ref,
        }

    def is_debit(self) -> bool:
        return self.kind in {"capture", "fee"}


_LINES: list[JournalLine] = []


def record_capture(user_id: int, amount: float, ref: str) -> JournalLine:
    line = JournalLine("capture", user_id, float(amount), ref)
    _LINES.append(line)
    return line


def record_void(user_id: int, amount: float, ref: str) -> JournalLine:
    line = JournalLine("void", user_id, float(amount), ref)
    _LINES.append(line)
    return line


def record_fee(user_id: int, amount: float, ref: str) -> JournalLine:
    line = JournalLine("fee", user_id, float(amount), ref)
    _LINES.append(line)
    return line


def lines_for(user_id: int) -> list[dict]:
    return [line.as_dict() for line in _LINES if line.user_id == user_id]


def lines_for_ref(ref: str) -> list[dict]:
    return [line.as_dict() for line in _LINES if line.ref == ref]


def captured_total(user_id: int | None = None) -> float:
    total = 0.0
    for line in _LINES:
        if user_id is not None and line.user_id != user_id:
            continue
        if line.kind == "capture":
            total += line.amount
        elif line.kind == "void":
            total -= line.amount
    return round(total, 2)


def has_capture(ref: str) -> bool:
    return any(line.kind == "capture" and line.ref == ref for line in _LINES)


def last_line() -> dict | None:
    if not _LINES:
        return None
    return _LINES[-1].as_dict()


def reset_store() -> None:
    _LINES.clear()

